import{z as l,x as s,o as e,c as d,q as r,j as o,D as E,d as A,s as n,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"价格冲击的微观基础","description":"","frontmatter":{"title":"价格冲击的微观基础","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-impact-microfoundations.md","filePath":"quant/obd-impact-microfoundations.md","lastUpdated":1791413859000}'),u={name:"quant/obd-impact-microfoundations.md"};function p(m,a,D,c,h,F){const t=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="价格冲击的微观基础" tabindex="-1">价格冲击的微观基础 <a class="header-anchor" href="#价格冲击的微观基础" aria-label="Permalink to &quot;价格冲击的微观基础&quot;">​</a></h1><div class="epigraph"><p>冲击律是平均意义上的响应函数；要用在某笔订单上，必须回答它对簿上哪个状态量取的平均。</p><footer>—— 据 Bouchaud 等, Trades, Quotes and Prices, 2018；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/obd-queue-dynamics">上一课</a>把队列动力学的验收钉在一张统计清单上：速率族对状态的依赖、耗尽与补量、存活与自相关。本课把视角从「簿怎么生成事件」转到「事件怎么搬价格」。冲击的两条经验律主干已经讲过：<a href="/quant/bouchaud-propagator">Bouchaud 传播核</a>的单笔线性响应与<a href="/quant/square-root-impact-law">平方根冲击律</a>的母单凹性；本课不重推这两条律，而是问它们的微观基础：冲击在簿上是哪个量的函数，机械耗尽与信息更新各占哪一段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把冲击律当成本表用是最常见的错法：同一规模的订单，在簿密度不同的两个日子，价格响应可以完全不同，平均化的冲击律却对两日给出同一个数。缺口不是再找一条更准的经验律，而是把冲击还原到簿的状态：主动成交先吃掉最优档的量（上一课的耗尽），中间价跳，限价补量随后把深度填回，价格一部分回落、一部分留下。这条微观路径的群体平均，就是传播核与母单冲击律观测到的东西。</p><p><span class="marginnote">术语翻译：冲击不是「砸盘」那种新闻用语，而是你自己订单造成的那部分价格位移。冲击律回答「规模翻倍，位移涨多少」——线性律说涨一倍，平方根律说只涨约 1.4 倍；本课问的是这个倍数在簿上由什么决定。</span></p><h3 id="机械与信息两条线" tabindex="-1">机械与信息两条线 <a class="header-anchor" href="#机械与信息两条线" aria-label="Permalink to &quot;机械与信息两条线&quot;">​</a></h3><p>冲击有两个来源。<a href="/quant/kyle-model">Kyle 模型</a>那条线是信息性的：成交被读成信号，做市商按流量调整价格，\\(\\lambda\\) 是信息含量的价格。队列动力学这条线是机械性的：量被吃掉、簿变薄、价格因为流动性暂时变贵。经验冲击是两线的叠加，分辨的抓手是回复：机械成分随补量部分回落，信息成分不回头——这与 <a href="/quant/bouchaud-propagator">Bouchaud 传播核</a>拆分暂时与永久是同一件事。</p><p><span class="marginnote">无套利给这条分解上了锁：Huberman 与 Stanzl 指出，若永久冲击对规模是凹的，来回买卖大单可以无风险盈利——凹性必须主要放在暂时项，永久项保持线性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把一次主动成交写成三步：立即耗散——成交档与邻近档的深度被抽走，剖面出现凹坑；弹性恢复——限价补量按速率族把凹坑填回，价格部分回落；残留——回复停止后的净位移。传播核 \\(G(\\tau)\\) 就是这三步在群体上的平均轮廓；母单的平方根来自单笔核在订单流记忆上的叠加与潜在订单簿的临界界面，<a href="/quant/square-root-impact-law">平方根冲击律</a>那课已经论证。工程上，条件化是关键动作：估计与使用冲击时，把 \\(Q/V\\) 与簿密度同时作为条件。潜在簿模型的检验口径：控制住密度之后，「根号」的残差应当大幅缩水。</p>',11)),(e(),o(i,null,{default:E(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILL%5B%22%E4%B8%BB%E5%8A%A8%E6%88%90%E4%BA%A4%22%5D%20--%3E%20DEP%5B%22%E6%B7%B1%E5%BA%A6%E8%80%97%E6%95%A3%EF%BC%9A%E5%87%B9%E5%9D%91%22%5D%0A%20%20DEP%20--%3E%20MID%5B%22%E4%B8%AD%E7%82%B9%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20MID%20--%3E%20REF%5B%22%E9%99%90%E4%BB%B7%E8%A1%A5%E9%87%8F%EF%BC%9A%E5%BC%B9%E6%80%A7%E6%81%A2%E5%A4%8D%22%5D%0A%20%20REF%20--%3E%20PERM%5B%22%E6%AE%8B%E7%95%99%E4%BD%8D%E7%A7%BB%EF%BC%9A%E6%B0%B8%E4%B9%85%E9%83%A8%E5%88%86%22%5D%0A%20%20REF%20--%3E%20TRANS%5B%22%E5%9B%9E%E8%90%BD%EF%BC%9A%E6%9A%82%E6%97%B6%E9%83%A8%E5%88%86%22%5D%0A%20%20PERM%20--%3E%20LAW%5B%22%E5%8F%A0%E5%8A%A0%E5%87%BA%E6%AF%8D%E5%8D%95%E5%86%B2%E5%87%BB%E5%BE%8B%22%5D%0A%20%20TRANS%20--%3E%20LAW%0A%20%20DEN%5B%22%E7%B0%BF%E5%AF%86%E5%BA%A6%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20LAW%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"凹性在簿的密度结构：限价量随距离累积成潜在分布，主动订单只激活它的薄壳，吃的量翻倍不等于穿透翻倍的深度，边际位移递减。衰减在订单流记忆：成交自相关，若响应不衰减，叠加起来价格会超扩散；传播核的幂律衰减正是把流量记忆对冲掉的形状。两条机制合起来也回答了「什么时候它不成立」：密度被外力扭曲（大额母单进行中、事件前后）或流量记忆被制度改变时，薄壳近似与对冲条件先后失效。",-1)),a[5]||(a[5]=B("p",null,"平方根的「根号」具体从簿上哪个结构长出来，值得单独画一遍：",-1)),(e(),o(i,null,{default:E(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20LB%5B%22%E6%BD%9C%E5%9C%A8%E7%B0%BF%3A%E9%99%90%E4%BB%B7%E9%87%8F%E9%9A%8F%E4%BB%B7%E6%A0%BC%E8%B7%9D%E7%A6%BB%E7%B4%AF%E7%A7%AF%E5%8F%98%E5%8E%9A%22%5D%20--%3E%20SH%5B%22%E6%AF%8D%E5%8D%95%E5%8F%AA%E6%BF%80%E6%B4%BB%E8%BF%91%E4%BB%B7%E8%96%84%E5%A3%B3%22%5D%0A%20%20SH%20--%3E%20Q%7B%22%E8%A7%84%E6%A8%A1%E7%BF%BB%E5%80%8D%E5%90%8E%22%7D%0A%20%20Q%20--%3E%7C%22%E4%BB%8D%E5%9C%A8%E8%96%84%E5%A3%B3%E5%86%85%22%7C%20C1%5B%22%E5%A4%9A%E6%8E%8F%E7%9A%84%E9%87%8F%E6%9C%89%E9%99%90%3A%E4%BD%8D%E7%A7%BB%E8%BE%B9%E9%99%85%E9%80%92%E5%87%8F%22%5D%0A%20%20Q%20--%3E%7C%22%E6%B7%B1%E5%A4%84%E5%AF%86%E5%BA%A6%E6%9B%B4%E9%AB%98%22%7C%20C2%5B%22%E5%90%8C%E6%A0%B7%E7%9A%84%E9%87%8F%E5%8F%AA%E9%9C%80%E6%9B%B4%E5%B0%8F%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20C1%20--%3E%20SQ%5B%22%E5%90%88%E6%88%90%3A%E4%BD%8D%E7%A7%BB%E8%BF%91%E4%BC%BC%E9%9A%8F%E8%A7%84%E6%A8%A1%E7%9A%84%E5%BC%80%E6%96%B9%E5%A2%9E%E9%95%BF%22%5D%0A%20%20C2%20--%3E%20SQ%0A%20%20SQ%20--%3E%20BRK%5B%22%E5%AF%86%E5%BA%A6%E8%A2%AB%E6%89%AD%E6%9B%B2(%E5%A4%A7%E5%8D%95%E8%BF%9B%E8%A1%8C%E4%B8%AD%2F%E4%BA%8B%E4%BB%B6%E5%89%8D%E5%90%8E)%E6%97%B6%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：按平方根律位移正比于规模的开方——下 100 万的位移是基准 c，下 400 万约 2c，下 900 万约 3c。规模翻 9 倍成本只翻 3 倍，多出的空间就是分批执行算法赚的钱；若冲击真是线性的，拆单将毫无意义。</span></p><p>把冲击条件化在簿状态上，是本课对上一课的回报：队列模型给出的深度、价差与补量速率正是冲击函数的自变量。不这么做，用全程平均的冲击律做执行与做市，会在薄簿日低估成本、在厚簿日高估成本。</p><p><span class="marginnote">常见误区：初学者以为执行算法的作用是「躲开冲击」。实际上机械与信息位移都躲不开，只能摊薄——把同样的量摊到更长窗口与更厚簿状态上执行，省下的正是凹性给的那部分差价，而不是让冲击消失。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单笔冲击不可识别：观测里混着同时到达的他人流量，能谈的只有平均响应。隐藏流动性让簿密度本身带测量误差，冰山与暗池吸收掉的那部分成交不会出现在凹坑里。自己的订单流有记忆：连续执行时，前面的执行改写后面的状态，冲击律的「其他不变」前提被自己破坏。体制依赖无法用一条曲线吸收：把 \\(G\\) 当不变的换算表，等于宣布参与者结构与簿密度形状恒定——本课给出它在簿上的成因。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>冲击的微观基础是三步：耗散、弹性恢复、残留；经验冲击律是这条路径的群体平均。</li><li>机械与信息两线叠加，分辨抓手是回复：暂时项随补量回落，永久项不回头。</li><li>无套利要求凹性留在暂时项、永久项线性（Huberman–Stanzl）。</li><li>凹性来自潜在簿密度与薄壳激活，衰减来自对订单流记忆的对冲。</li><li>使用冲击必须条件化在簿密度上：平均律不是成本表。</li><li>出处：Bouchaud 等, <em>Trades, Quotes and Prices</em>, 2018；Kyle, <em>Econometrica</em>, 1985；Huberman and Stanzl, <em>Econometrica</em>, 2004；市场语言见 Harris, <em>Trading and Exchanges</em>, 2003。</li></ul>',7))])}const b=l(u,[["render",p]]);export{C as __pageData,b as default};
